def min_unit(table,unit):
	if unit < 10000001:
		return table[unit]
	tempunit=1000000
	if unit%2 == 0:
		tempunit=min(tempunit,1+min_unit(table,unit/2))
	if unit%3 == 0:
		tempunit=min(tempunit,1+min_unit(table,unit/3))
	if unit%2 != 0 or unit%3 != 0:
		tempunit=min(tempunit,1+min_unit(table,unit -1))
	return tempunit

